E["60:0ebd951a"] = "Очок вміння цього тижня ще немає - очки кожного дня з'являться тут."
E["60:43495ebf"] = "Розчаклувати зелену й синю зброю та броню (Зачарування)."
E["60:6d37fe40"] = "Зараз на аукціоні немає - це остання побачена ціна."
E["60:7194fd30"] = "Список його рецептів ще не надійшов - він буде за мить."
E["60:8ee93299"] = "Цей сеанс, ваші загальні числа та риба навколо вас."
E["60:bc19fd02"] = "Помічник риболовлі вимкнено. Увімкніть його: Налаштування > Рибалка."
E["60:d1570092"] = "Майстри не втрачають зв'язку, а помилку в підземеллях виправлено."
E["60:db009607"] = "Професій ще не вивчено - зверніться до наставника в будь-якій столиці."
E["61:2a97b595"] = "Новини, посібники з професій і все про Mastercraft."
E["61:4522d60d"] = "Виберіть усе, Ctrl+C, потім вставте це в коментар на CurseForge."
E["61:5bc7a2d0"] = "На Forever ці зливки не дають очок вміння - підвищуйте вміння видобутком."
E["61:63a430e6"] = "Baganator від plusmouse - помічник банку з його вікном банку"
E["61:7a288c68"] = "Міні-посібник знову буде поруч із вікном професії."
E["61:c52edb09"] = "Користуєтеся іншим аддоном риболовлі? Вимкніть це - ця сторінка залишиться."
E["61:d4ffc24a"] = "Відкрийте будь-яке вікно професії один раз, і його рецепти з'являться тут."
E["61:ff37c3f2"] = "Матеріали у вашому банку: «Забрати матеріали» у банку дістає їх."
E["62:3680ba2a"] = "Жодного баченого рецепта - відкрийте вікна професій один раз."
E["62:3e483785"] = "Читання всього аукціону - кілька секунд. Тримайте його відкритим."
E["62:7cb5688a"] = "1 стос матеріалів для виготовлення у ваших сумках можна віднести до банку."
E["62:a9de152e"] = "Шукайте вище, перетягніть сюди предмет або натисніть «Стежити» на будь-якому рецепті."
E["62:b519d591"] = "Ці гравці підтримують Mastercraft пожертвою - дякуємо!"
E["62:e5e890c1"] = "Новий стиль потребує перезавантаження - Mastercraft запитає, коли ви завершите."
E["63:4e62cb7b"] = "Жоден допис не підходить - спробуйте «Усі» або вимкніть «Лише для моїх професій»."
E["63:8fbf5058"] = "Ви на межі 150% - далі відпочинок марний. Час виконувати завдання!"
E["63:94de7ae1"] = "Сканувати самостійно, коли я відкриваю аукціон, а ціни застарілі"
E["63:fbf5653c"] = "Ви побачите їхні рецепти, щойно вони відкриють вікно цієї професії."
E["64:10fbb11a"] = "Ctrl+C, щоб скопіювати, потім вставте на getmastercraft.com/crafters/add"
E["64:6e24c76e"] = "Ваша гра англійською, тож назви рецептів уже англійською."
E["64:6fca6a65"] = "Візьміть вудку, щоб закинути — кнопка «Спорядження» зробить це за вас."
E["64:a0fd3b4e"] = "Bazooka від mitchnull - панель, що показує запуск Mastercraft"
E["64:a18f0964"] = "Одним кліком запрошує до вашої групи всіх, чиї прохання ви прийняли."
E["64:e1db2519"] = "Підказки предметів враховують лише персонажів фракції, за яку ви граєте."
E["64:fd15e0c9"] = "Обраного ще немає - клацніть зірку на будь-якому рецепті, щоб зберегти його тут."
